"""
CFFI builder for the soroauth Python bindings.

This module defines the C interface and provides the FFI object that the main
package uses to call into libsoroauth via dlopen.
"""

from __future__ import annotations

import os
import platform
import sys
from pathlib import Path

from cffi import FFI

ffibuilder = FFI()

# C header definitions (mirrors libsoroauth.h generated by cgo)
ffibuilder.cdef("""
    // Version
    const char* SoroauthVersion(void);

    // Memory management
    void SoroauthFree(const char* ptr);

    // Preimage and payload
    const char* SoroauthPreimage(const char* entryB64, long long validUntilLedger, const char* networkPassphrase);
    const char* SoroauthPayload(const char* preimageB64);

    // Signing
    const char* SoroauthAuthorizeWithSeed(const char* entryB64, long long validUntilLedger, const char* networkPassphrase, const char* seedHex, const char* forAddress);
    const char* SoroauthAuthorizeWithSeeds(const char* entryB64, long long validUntilLedger, const char* networkPassphrase, const char* seedsCSV, const char* forAddress);
    const char* SoroauthWriteSignature(const char* entryB64, long long validUntilLedger, const char* networkPassphrase, const char* forAddress, const char* signatureScvalB64);

    // Inspection
    const char* SoroauthInspect(const char* entryB64);

    // Risk analysis
    const char* SoroauthAnalyze(const char* entryB64, long long currentLedger);

    // Rendering
    const char* SoroauthRenderInvocations(const char* entryB64);
    const char* SoroauthRenderTree(const char* entryB64);
""")

# This is a pure Python module using dlopen, not a C extension.
# set_source with None source creates a pure Python module.
ffibuilder.set_source("sorauth._ffi", None)


def _find_library_path() -> str:
    """Find the libsoroauth shared library path."""
    # 1. Environment variable override
    if env_path := os.environ.get("SOROAUTH_LIB"):
        return env_path

    # 2. Package-relative (wheel install)
    try:
        pkg_root = Path(__file__).resolve().parent
    except NameError:
        # __file__ not defined (e.g., when exec'd)
        pkg_root = Path.cwd() / "soroauth"
    lib_dir = pkg_root / "lib"
    if lib_dir.exists():
        for pattern in ("libsoroauth.so", "libsoroauth.dylib", "libsoroauth.dll"):
            matches = list(lib_dir.glob(pattern))
            if matches:
                return str(matches[0])

    # 3. Development build
    dev_lib = pkg_root.parent.parent.parent / "bindings" / "c" / "dist"
    if dev_lib.exists():
        for pattern in ("libsoroauth.so", "libsoroauth.dylib", "libsoroauth.dll"):
            matches = list(dev_lib.glob(pattern))
            if matches:
                return str(matches[0])

    # 4. System library name (let dlopen search system paths)
    if platform.system() == "Windows":
        return "libsoroauth.dll"
    elif platform.system() == "Darwin":
        return "libsoroauth.dylib"
    else:
        return "libsoroauth.so"


# Load the library
_lib_path = _find_library_path()
_lib = ffibuilder.dlopen(_lib_path)

# Expose the loaded library for the main package
lib = _lib